// santiagodie.com: behaviour only. Every word on the page is already in the HTML
// generated by tools/build.py; this script never injects content.
// Handles: header state on scroll, mobile menu, language menu
// (menu button pattern) and the dismissible language suggestion.

(() => {
  "use strict";

  const header = document.querySelector("[data-header]");
  const toggle = document.querySelector("[data-menu-toggle]");
  const menu = document.querySelector("[data-menu]");
  const compact = window.matchMedia("(max-width: 63.99em)");
  const lang = document.documentElement.lang;
  const langSwitch = document.querySelector("[data-lang-switch]");
  const langButton = langSwitch.querySelector("button");
  const langItems = [...langSwitch.querySelectorAll("[role='menuitem']")];


  // Storage can throw (private mode, blocked cookies), so every access is guarded.
  const storage = {
    get(key) {
      try { return window.localStorage.getItem(key); } catch { return null; }
    },
    set(key, value) {
      try { window.localStorage.setItem(key, value); } catch { /* not persisted */ }
    },
  };

  // Header: transparent over the hero, navy once the page scrolls -------------

  const onScroll = () => header.toggleAttribute("data-scrolled", window.scrollY > 16);
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // Mobile menu: a full-screen modal dialog below 64em -------------------------
  // On desktop the same element is the navigation bar, so it only becomes a dialog
  // (role, aria-modal, name) on narrow screens. While it is open the page behind it
  // does not scroll, focus stays inside, and the progress line and the About chat
  // hold still (they listen for "menu:toggle").

  const closeButton = menu.querySelector("[data-menu-close]");
  const root = document.documentElement;

  function asDialog(on) {
    if (on) {
      menu.setAttribute("role", "dialog");
      menu.setAttribute("aria-modal", "true");
      menu.setAttribute("aria-label", menu.dataset.menuLabel);
    } else {
      ["role", "aria-modal", "aria-label"].forEach((name) => menu.removeAttribute(name));
    }
  }

  const isOpen = () => header.hasAttribute("data-menu-open");

  function setMenu(open, { returnFocus = false, instant = false } = {}) {
    open = open && compact.matches;
    if (open === isOpen()) {
      menu.inert = compact.matches && !open;
      return;
    }
    toggle.setAttribute("aria-expanded", String(open));
    // Escape closes at once (lot 9): no 0.7 s exit after a key that means "away".
    if (instant) {
      header.setAttribute("data-menu-instant", "");
      requestAnimationFrame(() => requestAnimationFrame(() => header.removeAttribute("data-menu-instant")));
    }
    header.toggleAttribute("data-menu-open", open);
    root.toggleAttribute("data-menu-open", open);
    menu.inert = compact.matches && !open;
    if (open) {
      menu.querySelector("[data-nav-link]")?.focus({ preventScroll: true });
    } else {
      closeLang();
      if (returnFocus) toggle.focus({ preventScroll: true });
    }
    document.dispatchEvent(new CustomEvent("menu:toggle", { detail: open }));
  }

  // Tab and Shift+Tab go round the dialog's own controls.
  function trapFocus(event) {
    if (event.key !== "Tab" || !isOpen()) return;
    const stops = [...menu.querySelectorAll("a[href], button:not([disabled])")]
      .filter((el) => el.getClientRects().length && getComputedStyle(el).visibility !== "hidden");
    const first = stops[0];
    const last = stops[stops.length - 1];
    if (event.shiftKey && (document.activeElement === first || !menu.contains(document.activeElement))) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && (document.activeElement === last || !menu.contains(document.activeElement))) {
      event.preventDefault();
      first.focus();
    }
  }

  toggle.addEventListener("click", () => setMenu(true));
  closeButton.addEventListener("click", () => setMenu(false, { returnFocus: true }));
  // A section link closes the menu and the page scrolls to it (the browser follows
  // the link once the scroll lock is lifted).
  menu.addEventListener("click", (event) => {
    if (event.target.closest("[data-nav-link]")) setMenu(false);
  });
  document.addEventListener("keydown", trapFocus);
  compact.addEventListener("change", () => {
    setMenu(false);
    asDialog(compact.matches);
    menu.inert = compact.matches;
  });
  asDialog(compact.matches);
  menu.inert = compact.matches;

  // Language menu (WAI-ARIA menu button: arrows, Home/End, Enter, Escape) -------

  function openLang(focusIndex = 0) {
    langSwitch.setAttribute("data-open", "");
    langButton.setAttribute("aria-expanded", "true");
    langItems[Math.max(0, Math.min(focusIndex, langItems.length - 1))].focus({ preventScroll: true });
  }

  function closeLang({ returnFocus = false } = {}) {
    if (!langSwitch.hasAttribute("data-open")) return;
    langSwitch.removeAttribute("data-open");
    langButton.setAttribute("aria-expanded", "false");
    if (returnFocus) langButton.focus();
  }

  langButton.addEventListener("click", () => {
    if (langSwitch.hasAttribute("data-open")) closeLang();
    else openLang(Math.max(0, langItems.findIndex((item) => item.hasAttribute("aria-current"))));
  });

  langButton.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      event.stopPropagation(); // the menu's own handler would move focus a second time
      openLang(event.key === "ArrowDown" ? 0 : langItems.length - 1);
    }
  });

  langSwitch.addEventListener("keydown", (event) => {
    const index = langItems.indexOf(document.activeElement);
    if (index === -1) return;
    const moves = { ArrowDown: index + 1, ArrowUp: index - 1, Home: 0, End: langItems.length - 1 };
    if (event.key in moves) {
      event.preventDefault();
      langItems[(moves[event.key] + langItems.length) % langItems.length].focus({ preventScroll: true });
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeLang({ returnFocus: true });
    } else if (event.key === "Tab") {
      closeLang();
    }
  });

  // Keep the reader in the same section when switching language (from the
  // dropdown or from the row of languages).
  document.querySelectorAll("[data-lang-link]").forEach((item) => {
    item.addEventListener("click", () => {
      const section = currentSection();
      if (section && !item.hasAttribute("aria-current")) item.hash = section;
    });
  });

  document.addEventListener("click", (event) => {
    if (!langSwitch.contains(event.target)) closeLang();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (langSwitch.hasAttribute("data-open")) closeLang({ returnFocus: true });
    else if (isOpen()) setMenu(false, { returnFocus: true, instant: true });
  });

  // Changing language (lot 9): the page that leaves names its current section's number
  // and title and stores where the title is, for the next page to land there (see the
  // script in <head>). Hovering the selector prefetches the other languages.
  addEventListener("pageswap", (event) => {
    const section = event.viewTransition && document.getElementById(currentSection());
    const title = section?.querySelector(".section__title");
    if (!title) return;
    try { sessionStorage.setItem("vt", JSON.stringify({ id: section.id, top: title.getBoundingClientRect().top })); } catch { return; }
    [[title, "vt-title"], [section.querySelector(".section__num"), "vt-num"]].forEach(([el, name]) => {
      el.style.viewTransitionName = name;
      el.dataset.vt = "";
    });
  });
  if (HTMLScriptElement.supports?.("speculationrules")) {
    langButton.addEventListener("pointerenter", () => {
      const rules = document.createElement("script");
      rules.type = "speculationrules";
      rules.textContent = JSON.stringify({ prefetch: [{ urls: langItems.filter((a) => !a.hasAttribute("aria-current")).map((a) => a.href), eagerness: "immediate" }] });
      document.head.append(rules);
    }, { once: true });
  }

  // Current section: js/scroll.js marks it in the navigation, following the tip of
  // the progress line.

  function currentSection() {
    const link = document.querySelector("[data-nav-link][aria-current]");
    return link ? link.getAttribute("href").slice(1) : null;
  }

  // Language suggestion: a hint, never a redirect -------------------------------

  // The inline script in <head> already chose the language to suggest (if any)
  // before the first paint, so the bar never pushes the page down.
  const DISMISS_KEY = "lang-suggest-dismissed";
  const preferred = document.documentElement.dataset.suggest;
  const suggestion = preferred && document.querySelector(`.lang-suggest[data-suggest="${preferred}"]`);

  if (suggestion && preferred !== lang) {
    suggestion.hidden = false;
    suggestion.querySelector("[data-suggest-dismiss]").addEventListener("click", () => {
      storage.set(DISMISS_KEY, "1");
      // Focus goes to the header's first control in view (the logo, or on phones over
      // the hero, where the logo is hidden, the menu button), not back to the page.
      [...header.querySelectorAll("a[href], button")]
        .find((el) => el.getClientRects().length && getComputedStyle(el).visibility !== "hidden")
        ?.focus({ preventScroll: true });
      const gone = () => {
        suggestion.hidden = true;
        delete document.documentElement.dataset.suggest;
      };
      if (!motionOk.matches) return gone();
      // It gathers up rather than vanishing, so the page below rises instead of jumping.
      const cs = getComputedStyle(suggestion);
      suggestion.style.overflow = "hidden";
      suggestion.animate({
        height: [cs.height, "0px"], paddingTop: [cs.paddingTop, "0px"], paddingBottom: [cs.paddingBottom, "0px"],
        borderBottomWidth: [cs.borderBottomWidth, "0px"], opacity: [1, 0],
      }, { duration: time("--dur-reveal-out"), easing: EASE }).finished.then(gone);
    });
  }

  // Disclosures (lot 8), one engine for all; see DESIGN.md, Disclosure.
  const EASE = "cubic-bezier(0.23, 1, 0.32, 1)";
  const motionOk = matchMedia("(prefers-reduced-motion: no-preference)");
  // Times from styles.css (--dur-reveal in, --dur-reveal-out out); the blocks start at
  // these shares of the opening, each lasting 60 % of it: the last lands before it ends.
  const STAGGER = [0.07, 0.16, 0.23, 0.29, 0.33, 0.36];
  const time = (name) => parseFloat(getComputedStyle(root).getPropertyValue(name));
  const sum = (list) => list.reduce((a, b) => a + b, 0);
  const signal = (name, detail) => document.dispatchEvent(new CustomEvent(name, { detail }));
  let moving = 0;

  // o: parts (grow), kids (follow, staggered up to cap), anchor (kept still on closing;
  // gets the focus back), shift (anchor above the fold), force (keep what is below
  // still), shown(), start() (state at once) and shut() (once closed).
  function fold(host, open, animate, o) {
    const turning = !!host._anims; // turn back from where it is
    const from = o.parts.map((p) => (o.shown?.() === false ? 0 : p.getBoundingClientRect().height));
    const fade = o.kids.map((k) => +getComputedStyle(k).opacity);
    host._anims?.forEach((a) => a.cancel());
    const token = host._token = (host._token || 0) + 1;
    host._anims = null;
    o.start();
    if (!open && o.parts.some((p) => p.contains(document.activeElement))) o.anchor.focus({ preventScroll: true });
    let fix = () => {};
    const end = () => {
      o.parts.forEach((p) => { p.inert = false; });
      host.removeAttribute("data-moving");
      if (!open) o.shut?.();
      fix();
      root.style.overflowAnchor = host._anims = null;
      if (host._held && !(host._held = false) && !--moving) signal("disclosure:motion", false);
    };
    if (!animate || !motionOk.matches) {
      end();
      if (open && animate) o.kids.forEach((k) => k.animate({ opacity: [0, 1] }, { duration: 150, easing: "ease-out" }));
      return;
    }
    if (!host._held && (host._held = true) && !moving++) signal("disclosure:motion", true);
    host.setAttribute("data-moving", "");
    root.style.overflowAnchor = "none";
    o.parts.forEach((p) => { p.inert = !open; });
    const to = o.parts.map((p) => (open ? p.scrollHeight : 0));
    const full = time(open ? "--dur-reveal" : "--dur-reveal-out");
    const ms = full * Math.max(0.35, Math.abs(sum(to) - sum(from)) / (sum(o.parts.map((p) => p.scrollHeight)) || 1));
    const anims = host._anims = o.parts.map((p, i) => p.animate({ height: [`${from[i]}px`, `${to[i]}px`] }, { duration: ms, easing: EASE, fill: "forwards" }));
    o.kids.forEach((k, i) => anims.push(open
      ? k.animate({ opacity: [turning ? fade[i] : 0, 1], transform: ["translateY(8px)", "none"] },
        { duration: full * 0.6, delay: turning ? 0 : full * STAGGER[Math.min(i, (o.cap || 6) - 1)], easing: EASE, fill: "backwards" })
      : k.animate({ opacity: [fade[i], 0] }, { duration: Math.min(full / 2, ms), easing: EASE, fill: "forwards" })));
    const now = document.timeline.currentTime; // start now: a turn-back never stalls
    anims.forEach((a) => { a.startTime = now; });
    if (!open) {
      // The anchor stays if in view; otherwise what is below does (scrolling in-frame).
      const box = o.anchor.getBoundingClientRect();
      const top = header.getBoundingClientRect().bottom;
      const total = sum(from) || 1;
      const y1 = box.top >= top - 1 && box.bottom <= innerHeight + 1 && !o.force ? box.top
        : Math.min(Math.max(box.top + (o.shift ? total : 0), top), innerHeight - box.height);
      fix = () => {
        const p = 1 - sum(o.parts.map((x) => x.getBoundingClientRect().height)) / total;
        const dy = o.anchor.getBoundingClientRect().top - box.top - (y1 - box.top) * p;
        if (Math.abs(dy) >= 0.5) scrollBy({ top: dy, behavior: "instant" });
        signal("disclosure:frame");
      };
      const keep = () => {
        if (host._token === token && host.hasAttribute("data-moving")) {
          fix();
          requestAnimationFrame(keep);
        }
      };
      requestAnimationFrame(keep);
    }
    Promise.all(anims.map((a) => a.finished)).then(() => {
      if (host._token !== token) return;
      end();
      anims.forEach((a) => a.cancel());
    }, () => {});
  }

  // Featured cards on phones (lot 7): folded to title and technologies until "View
  // details". CSS folds them in one column only, so desktop is untouched.
  const features = [...document.querySelectorAll(".card--feature")];
  const foldCard = (card, open, animate) => {
    const button = card.querySelector(".card__toggle");
    const parts = [...card.querySelectorAll(".card__detail")];
    fold(card, open, animate && compact.matches, {
      parts, kids: parts.flatMap((p) => [...p.children]), anchor: button,
      start() {
        button?.setAttribute("aria-expanded", open);
        if (open) card.removeAttribute("data-collapsed");
      },
      shut: () => card.setAttribute("data-collapsed", ""),
    });
  };
  features.forEach((card) => {
    foldCard(card, false, false);
    const button = card.querySelector(".card__toggle");
    button?.addEventListener("click", () => foldCard(card, button.getAttribute("aria-expanded") === "false", true));
  });

  // More projects and More skills: native <details> (as ever without JavaScript); the
  // summary's click is taken over, [open] still changes at once.
  document.querySelectorAll("details.more").forEach((details) => {
    const summary = details.querySelector("summary");
    const body = details.querySelector(".more__body");
    const go = (open, force) => fold(details, open, true, {
      parts: [body], kids: [...body.querySelectorAll(".more__list > li, .skills__group, .more__hide")],
      cap: body.querySelector(".more__list") ? 4 : 6, anchor: summary, shift: true, force,
      shown: () => details.open || details.hasAttribute("data-moving"),
      start: () => { details.open = details._mine = open; },
    });
    details._go = go;
    summary.addEventListener("click", (event) => {
      event.preventDefault();
      go(!details.open);
    });
    details.querySelector("[data-more-hide]")?.addEventListener("click", () => go(false, true));
  });

  // Arriving at a card (#p-<id>: the hero's index, a link, or on load; lot 9): first the
  // scroll lands, then the card unfolds (its top stays put) and its frame traces. A card
  // inside More projects opens it the same way, then comes into view in its row.
  const landed = (el, then) => {
    let done = false;
    const go = () => {
      if (done) return;
      done = true;
      removeEventListener("scrollend", go);
      then();
    };
    addEventListener("scrollend", go);
    setTimeout(go, 1200); // no scrollend in this browser, or it never fired
    // Already where the scroll would leave it (under the header): nothing to wait for.
    if (Math.abs(el.getBoundingClientRect().top - parseFloat(getComputedStyle(root).scrollPaddingTop)) < 2) go();
  };
  const arrive = () => {
    const target = document.getElementById(location.hash.slice(1));
    const details = target?.closest("details.more");
    if (features.includes(target)) {
      target.scrollIntoView();
      landed(target, () => {
        if (target.hasAttribute("data-collapsed")) foldCard(target, true, true);
        target.removeAttribute("data-arrived");
        void target.offsetWidth; // trace again on a second arrival
        target.setAttribute("data-arrived", "");
      });
    } else if (details?._mine) {
      target.scrollIntoView({ block: "nearest", inline: "nearest" });
    } else if (details) {
      // The browser would open it at once and scroll past its summary: the hash is set
      // aside while the page lands on the summary, and put back when the card is shown.
      const hash = location.hash;
      history.replaceState(history.state, "", location.pathname + location.search);
      details.open = false;
      const summary = details.querySelector("summary");
      summary.scrollIntoView();
      landed(summary, () => {
        details._go(true);
        setTimeout(() => {
          target.scrollIntoView({ block: "nearest", inline: "nearest" });
          history.replaceState(history.state, "", hash);
        }, motionOk.matches ? time("--dur-reveal") : 0);
      });
    }
  };
  window.addEventListener("hashchange", arrive);
  arrive();

  // More projects: the arrows move one
  // card and switch off at the ends, where the fades (without scroll timelines) go too.
  // (the one with a scrolling row: "More skills" uses the same component, without it)
  const more = document.querySelector(".more__row")?.closest(".more");
  if (more) {
    const row = more.querySelector(".more__row");
    const nav = more.querySelector(".more__nav");
    const fallback = !CSS.supports("animation-timeline: scroll()");
    let frame = 0;
    const ends = () => {
      frame = 0;
      const x = row.scrollLeft, at = [x < 2, x > row.scrollWidth - row.clientWidth - 2];
      [...nav.children].forEach((arrow, i) => arrow.setAttribute("aria-disabled", at[i]));
      nav.hidden = at[0] && at[1]; // nothing to scroll (one card): no arrows
      if (fallback) at.forEach((end, i) => row.toggleAttribute(i ? "data-end" : "data-start", !end));
    };
    nav.onclick = ({ target }) => {
      const arrow = target.closest("[aria-disabled=false]");
      if (arrow) row.scrollBy({ left: arrow.dataset.dir * (row.querySelector("li").offsetWidth + 16), behavior: matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth" });
    };
    row.addEventListener("scroll", () => { frame ||= requestAnimationFrame(ends); }, { passive: true });
    more.addEventListener("toggle", ends);
    // A card reached with Tab comes whole into view, clear of the fades (scroll-padding).
    row.addEventListener("focusin", ({ target }) => target.closest("li").scrollIntoView({ block: "nearest", inline: "nearest" }));
    ends();
  }
})();
